para.latex:
\begin{eqnarray}
n_i &=& n-i+1 \\
R_i &=& \frac{\max_j |x_j-\overline{x}_i|}{s_i}
\quad\text{for a two-sided test} \\
R_i &=& \frac{\overline{x}_i-x_{min,i}}{s_i}
\quad\text{for a left-sided test} \\
R_i &=& \frac{x_{max,i}-\overline{x}_i}{s_i}
\quad\text{for a right-sided test}
\end{eqnarray}
